window.LESSONS_META={"1":{"title":"Fundamentos de la hiperautomatización","kick":"Episodio 01 · Fundamentos · Lección completa"},"2":{"title":"Introducción a los agentes inteligentes y la IA generativa","kick":"Episodio 02 · IA Generativa · Lección completa"},"3":{"title":"Prompt engineering para agentes","kick":"Episodio 03 · Prompting · Lección completa"},"4":{"title":"Herramientas de inteligencia artificial generativa","kick":"Episodio 04 · IA Generativa · Lección completa"},"5":{"title":"Creación de agentes con n8n","kick":"Episodio 05 · No-code · Lección completa"},"6":{"title":"Creación de agentes con Make","kick":"Episodio 06 · No-code · Lección completa"},"7":{"title":"Automatización y vibe coding con Claude","kick":"Episodio 07 · IA + Código · Lección completa"},"8":{"title":"Levantamiento de procesos y detección de oportunidades","kick":"Episodio 08 · Análisis · Lección completa"},"9":{"title":"Diseño funcional de soluciones y ciclo de vida de proyectos","kick":"Episodio 09 · Metodología · Lección completa"},"10":{"title":"Diseño de procesos BPMN","kick":"Episodio 10 · Modelado · Lección completa"}};
window.LESSONS={"1":[{"type":"title","dur":20,"eyeb":"Bienvenido","h2":"Todo equipo tiene un trabajo que alguien repite sin parar","sub":"Copiar datos, armar reportes, responder los mismos mensajes. Necesario, pero mecánico.","cap":"En todo equipo hay tareas que alguien repite una y otra vez: necesario, pero mecánico. Esta lección trata de cómo liberarte de eso.","narr":"Bienvenido a la primera lección. Empecemos por algo que seguramente reconoce: en todo equipo hay tareas que alguien repite una y otra vez. Copiar datos, armar reportes, responder los mismos mensajes. Trabajo necesario, pero mecánico. Esta lección trata de cómo liberarte de eso."},{"type":"list","dur":16,"eyeb":"Qué va a aprender","h2":"Tres cosas, en pocos minutos","items":[["1","Qué es la hiperautomatización","y en qué se diferencia de automatizar"],["2","Qué es un flujo","y de qué cuatro piezas está hecho"],["3","Un flujo real","funcionando, paso a paso"]],"cap":"En esta lección: qué es la hiperautomatización, qué es un flujo y sus piezas, y un flujo real paso a paso.","narr":"En los próximos minutos vas a entender tres cosas: qué es realmente la hiperautomatización, qué es un flujo y de qué está hecho, y cómo se ve un flujo funcionando en un caso real."},{"type":"compare","dur":19,"eyeb":"La distinción","h2":"Automatizar no es lo mismo que hiperautomatizar","colA":["Automatización","Una tarea suelta","Que una acción puntual ocurra sola, con reglas fijas. Ej.: enviar un correo automático."],"colB":["Hiperautomatización","Procesos completos + IA","Conectar varias tareas y sumarles inteligencia artificial, para resolver un proceso entero con criterio."],"cap":"Automatizar = una tarea suelta con reglas fijas. Hiperautomatizar = procesos completos conectados, con IA y criterio.","narr":"Primero, una distinción importante. Automatizar es hacer que una tarea puntual ocurra sola, con reglas fijas: por ejemplo, que un correo se envíe sin que lo escribas cada vez. La hiperautomatización va más allá: conecta varias de esas tareas y les suma inteligencia artificial, para que procesos enteros se resuelvan de principio a fin, con criterio, no solo con reglas rígidas."},{"type":"list","dur":16,"eyeb":"Por qué importa","h2":"No es moda: resuelve tres problemas reales","items":[["⏱","Recupera horas","El tiempo que hoy se va en tareas repetitivas"],["🎯","Menos errores","Se acaban las fallas de copiar y pegar a mano"],["📈","Escala sin más esfuerzo","Crece el trabajo, no su carga manual"]],"cap":"Importa por tres razones: recupera horas, reduce errores humanos y te deja escalar sin sumar trabajo manual.","narr":"¿Por qué molestarte con esto? Por tres razones muy concretas: recuperas horas que hoy se pierden en tareas repetitivas, reduces los errores humanos de copiar y pegar, y puedes crecer sin sumar más trabajo manual cada vez."},{"type":"define","dur":15,"eyeb":"El concepto central","h2":"Todo se construye sobre una idea: el flujo","def":"Un <b>flujo</b> es una secuencia de pasos que se ejecutan <b>solos</b>, en orden, para lograr un resultado — sin que intervengas.","cap":"Un flujo es una secuencia de pasos que se ejecutan solos, en orden, para lograr un resultado, sin que intervengas.","narr":"Toda hiperautomatización se construye sobre una idea simple: el flujo. Un flujo es una secuencia de pasos que se ejecutan solos, en orden, para lograr un resultado, sin que intervengas en el medio."},{"type":"pieces","dur":15,"eyeb":"La anatomía","h2":"Existen miles de flujos, pero todos tienen 4 piezas","pieces":[["⏰","Detonante","Qué lo activa"],["📊","Datos","De dónde saca"],["🤖","Criterio","Qué decide (IA)"],["📧","Resultado","Qué entrega"]],"cap":"Aunque existan miles de flujos distintos, todos comparten la misma anatomía: cuatro piezas.","narr":"Y aunque existan miles de flujos distintos, todos comparten la misma anatomía: cuatro piezas. Vamos a verlas una por una, porque entenderlas es entender el curso entero."},{"type":"spot","dur":15,"snum":"Pieza 1 de 4","sic":"⏰","stitle":"El detonante","stext":"Es lo que pone el flujo en marcha. Sin detonante, nada arranca.","sex":"Una hora · un correo que llega · un formulario enviado","cap":"Pieza 1: el detonante. Lo que pone el flujo en marcha: una hora, un correo, un formulario.","narr":"La primera pieza es el detonante: lo que pone el flujo en marcha. Puede ser una hora del día, un correo que llega, un formulario que alguien envía. Sin un detonante, el flujo nunca arranca."},{"type":"spot","dur":13,"snum":"Pieza 2 de 4","sic":"📊","stitle":"Los datos","stext":"De dónde toma la información con la que va a trabajar.","sex":"Una planilla · una base · un mensaje","cap":"Pieza 2: los datos. De dónde toma la información: una planilla, una base, un mensaje.","narr":"La segunda pieza son los datos: de dónde toma la información con la que va a trabajar. Una planilla, una base de datos, el contenido de un mensaje. El flujo va a buscarlos donde ya viven."},{"type":"spot","dur":16,"snum":"Pieza 3 de 4","sic":"🤖","stitle":"El criterio","stext":"Qué decide o transforma con esos datos. Aquí entra la inteligencia artificial.","sex":"Resume · clasifica · redacta · decide","cap":"Pieza 3: el criterio. Qué se decide o transforma. Aquí entra la IA: resume, clasifica, redacta.","narr":"La tercera pieza es el criterio: qué se decide o se transforma con esos datos. Y aquí es donde entra la inteligencia artificial. En lugar de reglas rígidas, la IA puede resumir, clasificar, redactar o decidir, adaptándose a cada caso."},{"type":"spot","dur":13,"snum":"Pieza 4 de 4","sic":"📧","stitle":"El resultado","stext":"Lo que el flujo finalmente entrega, ya terminado.","sex":"Un correo · un registro · una alerta","cap":"Pieza 4: el resultado. Lo que el flujo entrega, ya terminado: un correo, un registro, una alerta.","narr":"Y la cuarta pieza es el resultado: lo que el flujo finalmente entrega, ya terminado. Un correo enviado, un registro guardado, una alerta que salta. El objetivo por el que existe todo el flujo."},{"type":"flow","dur":19,"eyeb":"Ejemplo 1","h2":"El reporte del lunes, pieza por pieza","nodes":[["⏰","Detonante","Lunes 9:00"],["📊","Datos","Tu planilla"],["🤖","Criterio","IA resume"],["📧","Resultado","Correo al equipo"]],"cap":"Ejemplo: cada lunes a las 9 (detonante) lee tu planilla (datos), la IA resume (criterio) y envía el correo al equipo (resultado). Cero intervención.","narr":"Juntemos las cuatro piezas en un caso real: el reporte de ventas de cada lunes. El detonante: lunes a las nueve. Los datos: tu planilla de ventas. El criterio: la inteligencia artificial la resume en tres líneas. El resultado: el correo sale al equipo. Cuatro piezas, cero intervención tuya."},{"type":"flow","dur":19,"eyeb":"Ejemplo 2","h2":"El mismo esquema sirve para atención al cliente","nodes":[["💬","Detonante","Llega un mensaje"],["📇","Datos","Historial del cliente"],["🤖","Criterio","IA redacta respuesta"],["📤","Resultado","Respuesta enviada"]],"cap":"El mismo esquema: llega un mensaje (detonante), se lee el historial (datos), la IA redacta (criterio) y se responde (resultado).","narr":"Y no sirve solo para reportes. El mismo esquema resuelve, por ejemplo, la atención de consultas: llega un mensaje, ese es el detonante; se lee el historial del cliente, esos son los datos; la inteligencia artificial redacta una respuesta adecuada, ese es el criterio; y se envía, ese es el resultado. Las mismas cuatro piezas, otro problema resuelto."},{"type":"chips","dur":16,"eyeb":"Dónde vive esto","h2":"Se arma conectando bloques, sin programar","chips":[["🔗","Make"],["⚙️","n8n"],["⚡","Zapier"],["🧠","GPT"],["➕","y más"]],"cap":"Se construye en herramientas visuales (Make, n8n, Zapier) sumando modelos de IA. No necesitas programar: necesitas entender la lógica.","narr":"Todo esto se arma en herramientas visuales donde se conectan bloques, como Make, n8n o Zapier, sumándoles modelos de inteligencia artificial. La buena noticia: no necesitas programar. Necesitas entender la lógica que acabas de ver."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas que conviene entender bien","myths":[["No es magia"," ni una fórmula para hacerse rico"],["No reemplaza tu criterio"," lo potencia"],["No arregla el desorden"," primero entiendes el proceso, después lo automatizas"]],"cap":"La IA no es magia ni una fórmula de riqueza. No reemplaza tu criterio, lo potencia. Y no automatiza el caos: primero entiendes el proceso.","narr":"Un punto importante antes de seguir. La hiperautomatización no es magia ni una fórmula para hacerse rico. No reemplaza tu criterio: lo potencia. Y no funciona automatizando el desorden: primero entiendes bien el proceso, y después lo automatizas."},{"type":"pieces","dur":14,"eyeb":"Recapitulemos","h2":"Si reconoce estas 4 piezas, entiende cualquier flujo","pieces":[["⏰","Detonante","Qué lo activa"],["📊","Datos","De dónde saca"],["🤖","Criterio","Qué decide (IA)"],["📧","Resultado","Qué entrega"]],"cap":"Recap: todo flujo tiene detonante, datos, criterio y resultado. Reconocerlas es poder leer y diseñar cualquier automatización.","narr":"Recapitulemos. Todo flujo tiene cuatro piezas: detonante, datos, criterio y resultado. Si reconoces esas cuatro, ya puedes leer y diseñar cualquier automatización que se cruce en tu camino."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Un flujo no es magia: es criterio ordenado","sub":"Ya sabes qué es. En un momento lo vas a ver construirse, y después lo vas a armar tú mismo.","cap":"Un flujo es criterio bien ordenado. Ya sabes qué es. Sigue: verlo construirse y después armarlo tú mismo.","narr":"Eso es un flujo, y ese es el corazón de todo el curso. No es magia: es criterio bien ordenado. En un momento vas a ver uno construirse paso a paso, y después lo vas a armar tú mismo. Nos vemos en la práctica."}],"2":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"La IA generativa cambió las reglas de la automatización","sub":"Antes automatizabas tareas rígidas. Ahora puedes darle criterio a un programa.","cap":"La IA generativa permite automatizar con criterio, no solo con reglas fijas. Eso cambia todo.","narr":"Bienvenido a esta lección. Hasta hace poco, automatizar era encadenar reglas rígidas. La inteligencia artificial generativa cambió las reglas del juego: ahora puedes darle criterio a un programa, para que decida y redacte casi como lo harías tú. En los próximos minutos vas a entender por qué."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro ideas, en pocos minutos","items":[["1","Qué es un LLM","y cómo genera sus respuestas"],["2","Del chatbot al agente","la escalera de autonomía"],["3","La anatomía de un agente","de qué piezas está hecho"]],"cap":"En esta lección: qué es un LLM, la diferencia entre chatbot y agente, y de qué piezas está hecho un agente.","narr":"Vas a entender cuatro cosas: qué es un modelo de lenguaje y cómo genera sus respuestas, en qué se diferencia un chatbot de un agente, de qué piezas está hecho un agente, y dónde conviene usarlos de verdad."},{"type":"define","dur":15,"eyeb":"El concepto base","h2":"Primero, qué es un LLM","def":"Un <b>LLM</b> (modelo de lenguaje) es un programa entrenado con enormes cantidades de texto que <b>predice la siguiente palabra</b>, una tras otra, para formar respuestas coherentes.","cap":"Un LLM es un modelo entrenado con mucho texto que predice la siguiente palabra para formar respuestas.","narr":"Empecemos por la base. Un modelo de lenguaje grande, o LLM, es un programa entrenado con enormes cantidades de texto. En el fondo hace algo simple: predice la siguiente palabra, una tras otra. De esa predicción, repetida millones de veces, salen respuestas que suenan coherentes y útiles."},{"type":"pieces","dur":16,"eyeb":"Cómo funciona por dentro","h2":"Cuatro palabras que conviene que manejes","pieces":[["🧩","Token","Un pedazo de palabra"],["🪟","Contexto","Lo que puede leer a la vez"],["🌡️","Temperatura","Qué tan creativo responde"],["🌀","Alucinación","Cuando inventa con seguridad"]],"cap":"Token = pedazo de palabra. Contexto = lo que lee a la vez. Temperatura = creatividad. Alucinación = inventar con seguridad.","narr":"Cuatro palabras te van a servir siempre. Token: el modelo no lee letras ni palabras enteras, sino pedazos, y en tokens se mide todo. Contexto: cuánto texto puede tener presente a la vez. Temperatura: qué tan creativo o predecible responde. Y alucinación: cuando inventa un dato con total seguridad. Conocerlas te evita muchos errores."},{"type":"compare","dur":18,"eyeb":"La distinción clave","h2":"Un chatbot no es lo mismo que un agente","colA":["Chatbot","Responde y ya","Contesta lo que le preguntas. No actúa ni recuerda: cada mensaje empieza de cero."],"colB":["Agente","Persigue un objetivo","Planifica, usa herramientas y da varios pasos por su cuenta hasta lograr lo que le pediste."],"cap":"Chatbot: responde y ya. Agente: persigue un objetivo, planifica, usa herramientas y da varios pasos solo.","narr":"Aquí está la distinción que más importa. Un chatbot responde lo que le preguntas y ahí termina: no actúa ni recuerda. Un agente es otra cosa: le das un objetivo y, por su cuenta, planifica, usa herramientas y da varios pasos hasta lograrlo. El chatbot conversa; el agente trabaja."},{"type":"flow","dur":17,"eyeb":"La escalera de autonomía","h2":"Del que solo reacciona al equipo de agentes","nodes":[["💬","Reactivo","Responde"],["🧑‍💼","Asistente","Ayuda con contexto"],["🤖","Agente","Actúa solo"],["🕹️","Multiagente","Varios coordinados"]],"cap":"La autonomía sube por peldaños: reactivo, asistente, agente autónomo y varios agentes coordinados.","narr":"La autonomía no es de golpe: sube por peldaños. Primero el reactivo, que solo responde. Luego el asistente, que ayuda usando contexto. Después el agente, que actúa solo para cumplir una meta. Y arriba, varios agentes coordinados, cada uno con su tarea. Saber en qué peldaño estás te dice qué esperar."},{"type":"pieces","dur":16,"eyeb":"La anatomía","h2":"Un agente está hecho de cuatro piezas","pieces":[["🧠","Modelo","El que razona"],["🔧","Herramientas","Con qué actúa"],["📇","Memoria","Qué recuerda"],["🗺️","Planificación","Cómo se organiza"]],"cap":"Un agente = modelo (razona) + herramientas (actúa) + memoria (recuerda) + planificación (se organiza).","narr":"Todo agente, por complejo que parezca, tiene cuatro piezas. El modelo, que razona y decide. Las herramientas, con las que actúa en el mundo real: buscar, enviar, calcular. La memoria, que le permite recordar lo que ya pasó. Y la planificación, con la que se organiza en pasos. Reconoce estas cuatro y entiendes cualquier agente."},{"type":"spot","dur":16,"snum":"El motor del agente","sic":"🔁","stitle":"Razonar, actuar, observar","stext":"El agente piensa un paso, usa una herramienta, mira el resultado y decide el siguiente. Repite hasta terminar.","sex":"razona · actúa · observa · repite","cap":"El agente razona un paso, actúa con una herramienta, observa el resultado y repite hasta lograr la meta.","narr":"¿Y cómo hace todo eso? Con un ciclo muy simple que se repite. El agente razona el siguiente paso, usa una herramienta para ejecutarlo, observa qué resultado obtuvo, y con eso decide el paso siguiente. Razonar, actuar, observar, y otra vez. Ese bucle, repetido, es lo que hace que un agente parezca inteligente."},{"type":"flow","dur":18,"eyeb":"Un ejemplo real","h2":"Un agente que responde una consulta difícil","nodes":[["🎯","Objetivo","Responder al cliente"],["🗺️","Planea","Qué necesita saber"],["🔧","Consulta","Busca en tus datos"],["📤","Resuelve","Redacta y responde"]],"cap":"Ejemplo: recibe el objetivo, planea qué necesita, consulta tus datos con una herramienta y redacta la respuesta.","narr":"Veámoslo con un caso. Un cliente hace una pregunta compleja. El agente recibe el objetivo: responderle bien. Planea qué información necesita. Usa una herramienta para consultarla en tus datos. Y con eso redacta y envía la respuesta. Nadie le dictó cada paso: los decidió él para cumplir la meta."},{"type":"list","dur":16,"eyeb":"Dónde sí genera valor","h2":"No sirve para todo, pero brilla en esto","items":[["📨","Atención","Responder y clasificar consultas"],["🗂️","Back-office","Ordenar, resumir y registrar"],["📊","Análisis","Leer mucho y sacar conclusiones"]],"cap":"Brilla en atención al cliente, back-office (ordenar y resumir) y análisis de mucha información.","narr":"¿Dónde conviene usarlo? Donde hay mucho texto y criterio repetible. En atención, respondiendo y clasificando consultas. En el back-office, ordenando, resumiendo y registrando. Y en análisis, leyendo grandes volúmenes para sacar conclusiones. En cambio, para cálculos exactos o reglas fijas, hay mejores herramientas."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas para no llevarte una sorpresa","myths":[["No piensa como tú",", predice texto muy bien"],["No siempre acierta",", puede alucinar datos"],["No se deja sin vigilar",", necesita tu criterio"]],"cap":"El agente no piensa como un humano: predice texto. Puede alucinar. Y necesita tu supervisión.","narr":"Antes de seguir, tres advertencias sanas. Un modelo no piensa como tú: predice texto, y lo hace muy bien, pero no entiende como un humano. No siempre acierta: puede inventar un dato con seguridad. Y no se deja funcionando sin vigilancia: necesita tu criterio para las decisiones que importan. Bien usado, potencia tu trabajo; mal usado, te mete en problemas."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Un agente es un modelo con objetivo, herramientas y memoria","sub":"Ya sabes qué es y de qué está hecho. Sigue: verlo en acción y practicarlo tú mismo.","cap":"Un agente es un modelo con objetivo, herramientas y memoria. Sigue: verlo en acción y practicarlo.","narr":"Recapitulemos. Un modelo de lenguaje predice texto. Un agente es ese modelo con un objetivo, herramientas para actuar y memoria para recordar, moviéndose en un ciclo de razonar y actuar. Ya sabes qué es y de qué está hecho. Ahora sigue lo mejor: verlo en acción y armar el tuyo. Nos vemos en la práctica."}],"3":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Un agente hace exactamente lo que le pediste, no lo que querías","sub":"La diferencia entre un agente que sirve y uno que falla casi nunca está en el modelo: está en cómo lo instruyes.","cap":"Un agente hace lo que le pides, no lo que quieres. La calidad casi siempre está en la instrucción, no en el modelo.","narr":"Bienvenido a esta lección. Algo que descubres rápido al trabajar con agentes: hacen lo que les pides, no lo que tú querías. Y la diferencia entre uno que sirve y uno que falla casi nunca está en el modelo. Está en cómo lo instruyes."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Tres cosas, en pocos minutos","items":[["1","Un prompt profesional","de qué seis partes está hecho"],["2","Subir la precisión","con ejemplos y razonamiento por pasos"],["3","Blindar tu agente","salidas fijas y contra manipulación"]],"cap":"En esta lección: la estructura de un prompt profesional, técnicas para subir la precisión y cómo proteger tu agente.","narr":"En los próximos minutos vas a entender tres cosas: de qué partes se arma un prompt profesional, cómo subir su precisión sin cambiar de modelo, y cómo proteger tu agente para que entregue siempre lo que esperas."},{"type":"define","dur":15,"eyeb":"El concepto base","h2":"Primero, qué es un system prompt","def":"El <b>system prompt</b> es la instrucción fija que define quién es tu agente y cómo debe comportarse, <b>en cada conversación</b>, antes de que el usuario diga nada.","cap":"El system prompt es la instrucción fija que define quién es el agente y cómo se comporta, en cada conversación.","narr":"Empecemos por la base. El system prompt es la instrucción fija que le das a tu agente: define quién es y cómo se comporta. Se aplica en cada conversación, antes de que el usuario escriba una sola palabra. Es su carácter y sus reglas."},{"type":"pieces","dur":17,"eyeb":"La anatomía","h2":"Un buen prompt tiene seis partes: RCTFE","pieces":[["🎭","Rol","Quién es"],["🗂️","Contexto","Qué debe saber"],["🎯","Tarea","Qué tiene que hacer"],["🚧","Restricciones","Qué no debe hacer"],["📐","Formato","Cómo entregarlo"],["📎","Ejemplos","Cómo se ve bien"]],"cap":"Un prompt profesional tiene seis partes: rol, contexto, tarea, restricciones, formato y ejemplos.","narr":"Un prompt profesional no es un párrafo suelto: tiene seis partes. El rol, que dice quién es. El contexto, lo que debe saber. La tarea, qué tiene que hacer. Las restricciones, qué no debe hacer. El formato, cómo entregarlo. Y los ejemplos, cómo se ve bien hecho. Reconoce esas seis y sabrás leer y escribir cualquier prompt."},{"type":"spot","dur":16,"snum":"La pieza que más cambia","sic":"🚧","stitle":"Las restricciones","stext":"Decir qué NO hacer evita más problemas que decir qué hacer. Aquí acotas al agente para que no se salga del carril.","sex":"no inventes datos · no des precios · deriva si dudas","cap":"Las restricciones (qué NO hacer) previenen más fallas que las instrucciones positivas. Acotan al agente.","narr":"De esas seis, hay una que casi todos olvidan y es la que más problemas evita: las restricciones. Decirle qué no debe hacer acota al agente para que no se salga del carril. No inventes datos, no prometas precios, deriva a un humano si dudas. Un límite claro vale más que diez instrucciones."},{"type":"compare","dur":18,"eyeb":"La primera técnica","h2":"Explicar no es lo mismo que mostrar","colA":["Zero-shot","Solo describes","Le dices qué quieres con palabras y esperas que lo interprete bien. A veces basta, a veces no."],"colB":["Few-shot","Muestras ejemplos","Le das dos o tres ejemplos de entrada y salida. El agente copia el patrón y acierta mucho más."],"cap":"Zero-shot: solo describes la tarea. Few-shot: le muestras ejemplos y el agente copia el patrón. Acierta más.","narr":"La primera técnica para subir la precisión es simple: en vez de solo describir lo que quieres, muéstralo. Sin ejemplos, el agente interpreta a su manera. Con dos o tres ejemplos de entrada y salida, copia el patrón y acierta mucho más. A eso se le llama few-shot, y suele ser el arreglo más rápido."},{"type":"define","dur":16,"eyeb":"La segunda técnica","h2":"Pídele que piense antes de responder","def":"<b>Chain-of-thought</b> es pedirle al modelo que razone paso a paso antes de dar la respuesta. Al pensar en voz alta, comete menos errores en tareas con lógica.","cap":"Chain-of-thought: pedirle que razone paso a paso antes de responder. Reduce errores en tareas con lógica.","narr":"La segunda técnica se llama chain-of-thought, o cadena de razonamiento. Consiste en pedirle que piense paso a paso antes de responder. Igual que una persona, cuando el modelo razona en voz alta en vez de contestar de golpe, comete bastantes menos errores en tareas que llevan lógica."},{"type":"spot","dur":15,"snum":"Un paso más","sic":"🗳️","stitle":"Self-consistency","stext":"En decisiones difíciles, le pides varias respuestas y te quedas con la que más se repite. La mayoría suele tener razón.","sex":"pregunta 3 veces · compara · elige la común","cap":"Self-consistency: generar varias respuestas a la misma pregunta y quedarte con la mayoritaria. Sube la fiabilidad.","narr":"Y hay un paso más para lo importante: self-consistency. En vez de fiarte de una sola respuesta, le pides varias a la misma pregunta y te quedas con la que más se repite. Como en un jurado, la mayoría suele acertar. Cuesta un poco más, pero en decisiones difíciles vale la pena."},{"type":"flow","dur":18,"eyeb":"Salidas estructuradas","h2":"Cuando otro sistema lee la respuesta, el formato manda","nodes":[["💬","Instrucción","Pides JSON"],["🤖","Modelo","Razona y arma"],["📐","Formato","Estructura fija"],["🔗","Sistema","Lo usa sin fallar"]],"cap":"Si otro sistema consume la respuesta, pides un formato fijo como JSON para que se conecte sin romperse.","narr":"Hasta aquí hablamos de texto para leer. Pero muchas veces la respuesta la consume otro sistema, no una persona. Ahí el formato manda: le pides una estructura fija, como un JSON con campos definidos. Así el modelo entrega algo que la siguiente herramienta puede usar sin romperse."},{"type":"define","dur":16,"eyeb":"Conectar con el mundo","h2":"Function calling: del texto a la acción","def":"Con <b>function calling</b>, en vez de responder texto, el modelo elige una herramienta y arma los datos para usarla: buscar, agendar, enviar. Así el agente actúa.","cap":"Function calling: el modelo elige una herramienta y prepara sus datos, en vez de solo responder texto. Así actúa.","narr":"Y de ahí a la acción hay un paso: function calling. En lugar de contestar con palabras, el modelo elige una herramienta disponible y prepara los datos para usarla: buscar un dato, agendar, enviar un correo. Esta es la pieza que convierte a un modelo que conversa en un agente que hace cosas."},{"type":"spot","dur":16,"snum":"La amenaza","sic":"🛡️","stitle":"Prompt injection","stext":"Alguien esconde instrucciones en un mensaje o documento para que tu agente ignore sus reglas y haga otra cosa.","sex":"'ignora lo anterior' · texto oculto · datos con trampa","cap":"Prompt injection: instrucciones ocultas en la entrada del usuario para que el agente desobedezca sus reglas.","narr":"Ahora la parte que casi nadie enseña: la seguridad. El ataque más común se llama prompt injection. Alguien esconde instrucciones dentro de un mensaje o un documento para que tu agente ignore sus reglas y haga otra cosa. Un clásico: un texto que dice ignora todo lo anterior. Si tu agente lee datos de fuera, estás expuesto."},{"type":"list","dur":17,"eyeb":"Cómo blindarlo","h2":"Tres defensas que sí funcionan","items":[["🧱","Separa instrucciones y datos","que el agente sepa qué es orden y qué es contenido"],["🚧","Reglas que no se negocian","escritas en el system prompt, por encima de todo"],["👤","Humano en decisiones críticas","nada irreversible sin una revisión"]],"cap":"Defensas: separa instrucciones de datos, fija reglas innegociables en el system prompt y mantén un humano en lo crítico.","narr":"¿Cómo lo blindas? Con tres defensas que sí funcionan. Primero, separa las instrucciones de los datos, para que el agente sepa qué es una orden tuya y qué es solo contenido a procesar. Segundo, deja reglas innegociables en el system prompt, por encima de todo. Y tercero, para lo irreversible, siempre un humano revisando."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas para no llevarte una sorpresa","myths":[["No hay prompt perfecto",", se prueba y se ajusta"],["Más largo no es mejor",", claro le gana a extenso"],["El prompt no borra el riesgo",", lo reduce, no lo elimina"]],"cap":"No existe el prompt perfecto: se itera. Más largo no es mejor. Y ningún prompt elimina el riesgo del todo.","narr":"Antes de cerrar, tres advertencias honestas. No existe el prompt perfecto: se prueba, se mide y se ajusta con el uso. Más largo no es mejor; un prompt claro y corto casi siempre gana a uno extenso. Y ojo: un buen prompt reduce el riesgo de fallas y ataques, pero no lo elimina. Por eso tu criterio sigue siendo indispensable."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Instruir bien es la mitad del trabajo de un agente","sub":"Ya sabes estructurar, subir la precisión y proteger. Sigue: escribir tus propios prompts y probarlos.","cap":"Instruir bien es la mitad del trabajo. Sigue: escribir tus propios prompts, medirlos y ajustarlos.","narr":"Recapitulemos. Un buen prompt tiene rol, contexto, tarea, restricciones, formato y ejemplos. Subes su precisión con ejemplos y razonamiento por pasos, fijas el formato para conectarlo con otros sistemas, y lo blindas contra manipulación. Instruir bien es la mitad del trabajo. Ahora sigue lo mejor: escribir los tuyos y probarlos. Nos vemos en la práctica."}],"4":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Hay decenas de herramientas de IA, y todas dicen ser la mejor","sub":"Texto, imagen, voz, video. El problema no es que falten opciones: es elegir bien.","cap":"Sobran herramientas de IA generativa. El reto real no es encontrarlas: es elegir la adecuada para cada tarea.","narr":"Bienvenido a esta lección. Hoy hay decenas de herramientas de inteligencia artificial, y todas se anuncian como la mejor. El problema ya no es que falten opciones: es saber elegir la correcta para cada tarea. Eso es lo que vas a aprender aquí."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Tres cosas, en pocos minutos","items":[["1","El mapa de modelos","texto, imagen, voz y video"],["2","Cómo elegir bien","coste, calidad y privacidad"],["3","Cómo se conectan","APIs dentro de tus flujos"]],"cap":"En esta lección: el mapa de modelos por tipo, los criterios para elegir y cómo conectar una IA a tus flujos.","narr":"En los próximos minutos vas a entender tres cosas: cómo se organiza el mapa de modelos por tipo, qué criterios usar para elegir con cabeza, y cómo una herramienta de IA se conecta a tus automatizaciones."},{"type":"pieces","dur":16,"eyeb":"El mapa","h2":"Los modelos se agrupan por lo que producen","pieces":[["✍️","Texto","Escribe y razona"],["🎨","Imagen","Crea o edita visuales"],["🎙️","Voz","Habla y transcribe"],["🎬","Video","Genera clips"]],"cap":"Los modelos se agrupan por lo que producen: texto, imagen, voz y video. Cada familia resuelve un tipo de tarea.","narr":"Empecemos por ordenar el terreno. Los modelos se agrupan por lo que producen. Los de texto escriben y razonan. Los de imagen crean o editan visuales. Los de voz hablan y transcriben. Y los de video generan clips. Ubicar tu tarea en una de estas familias ya es medio camino."},{"type":"list","dur":18,"eyeb":"Modelos de texto","h2":"Los tres grandes que vas a escuchar nombrar","items":[["🟠","Claude","Fuerte en escritura larga y razonamiento cuidado"],["🟢","GPT","Versátil, con amplio ecosistema de herramientas"],["🔵","Gemini","Integrado con Google y buen manejo multimodal"]],"cap":"En texto, los tres nombres frecuentes son Claude, GPT y Gemini. Cada uno con fortalezas distintas.","narr":"En texto vas a escuchar sobre todo tres nombres. Claude destaca en escritura larga y razonamiento cuidado. GPT es muy versátil y tiene un ecosistema enorme. Y Gemini se integra con Google y maneja bien lo multimodal. No hay uno mejor para todo: hay uno mejor para cada caso."},{"type":"chips","dur":16,"eyeb":"Más allá del texto","h2":"Para imagen, voz y video también hay especialistas","chips":[["🎨","Midjourney"],["🖼️","DALL·E"],["🎙️","ElevenLabs"],["📝","Whisper"],["🎬","Runway"]],"cap":"Para imagen, voz y video hay herramientas especializadas: Midjourney, DALL-E, ElevenLabs, Whisper, Runway y más.","narr":"Fuera del texto hay especialistas muy buenos. Para imagen, Midjourney o DALL·E. Para voz, ElevenLabs genera locución natural y Whisper transcribe con precisión. Para video, Runway y similares. No necesitas memorizarlos: basta saber que cada tarea tiene su herramienta fuerte."},{"type":"compare","dur":18,"eyeb":"La primera decisión","h2":"En la nube o en tu propio equipo","colA":["En la nube","Rápido y potente","Usas modelos de última generación sin instalar nada. Pagas por uso y tus datos salen a un tercero."],"colB":["Local","Privado y bajo tu control","Corre en tu equipo o servidor. Más privacidad y sin costo por uso, pero exige hardware y mantenimiento."],"cap":"Nube: potente y sin instalar, pero tus datos salen. Local: privado y bajo tu control, pero exige hardware.","narr":"La primera gran decisión es dónde corre el modelo. En la nube tienes lo más potente sin instalar nada, pagando por uso, pero tus datos salen hacia un tercero. En local corre en tu propio equipo: más privacidad y sin costo por uso, aunque exige hardware y mantenimiento. La respuesta depende de qué tan sensibles sean tus datos."},{"type":"pieces","dur":17,"eyeb":"Cómo elegir","h2":"Tres criterios que sostienen toda decisión","pieces":[["💰","Coste","Cuánto cuesta cada uso"],["🎯","Calidad","Qué tan bueno es el resultado"],["🔒","Privacidad","Adónde van tus datos"]],"cap":"Toda elección se reduce a equilibrar tres cosas: coste por uso, calidad del resultado y privacidad de los datos.","narr":"Para elegir sin marearte, mide siempre tres cosas. El coste: cuánto pagas por cada uso. La calidad: qué tan bueno es el resultado para tu tarea. Y la privacidad: adónde van tus datos. Casi ninguna herramienta gana en las tres a la vez, así que eliges según lo que más pesa en tu caso."},{"type":"define","dur":15,"eyeb":"Un factor que se pasa por alto","h2":"La ventana de contexto también decide","def":"La <b>ventana de contexto</b> es cuánto texto puede leer el modelo de una sola vez. Si tu tarea usa documentos largos, <b>necesitas una ventana grande</b>.","cap":"La ventana de contexto es cuánto texto lee el modelo de una vez. Con documentos largos, necesitas una grande.","narr":"Hay un factor que muchos ignoran: la ventana de contexto. Es cuánto texto puede leer el modelo de una sola vez. Si vas a resumir un contrato de cien páginas, necesitas una ventana grande; si solo respondes mensajes cortos, una pequeña sobra. Elegir esto bien te ahorra errores y dinero."},{"type":"flow","dur":18,"eyeb":"Multimodal en la práctica","h2":"De una idea a un video, encadenando modelos","nodes":[["📝","Brief","Tu idea inicial"],["✍️","Texto","La IA escribe el guion"],["🎙️","Voz","Otra IA lo narra"],["🎬","Video","Se arma el clip"]],"cap":"Ejemplo multimodal: de un brief, un modelo escribe el guion, otro lo narra y otro genera el video.","narr":"Lo interesante es combinarlos. Mira un flujo real: partes de un brief, tu idea. Un modelo de texto escribe el guion. Un modelo de voz lo narra. Y un modelo de video arma el clip. Cada pieza la resuelve el especialista adecuado, y tú orquestas. Eso es generación multimodal en la práctica."},{"type":"spot","dur":16,"snum":"La pieza que une todo","sic":"🔌","stitle":"La API","stext":"Es la puerta por la que tu flujo le habla al modelo: le manda la petición y recibe la respuesta.","sex":"clave · petición · respuesta","cap":"La API es la puerta por la que tu automatización le habla al modelo: envía la petición y recibe la respuesta.","narr":"¿Y cómo conectas todo esto a tus automatizaciones? Con una API. Piensa en ella como la puerta por la que tu flujo le habla al modelo: le envías una petición con tu clave de acceso, y recibes la respuesta. Es el mismo mecanismo, sin importar si el modelo hace texto, voz o imagen."},{"type":"flow","dur":17,"eyeb":"Cómo se conecta","h2":"Una llamada a la API, paso a paso","nodes":[["🔑","Clave","Autentica quién eres"],["📨","Petición","Envías tu instrucción"],["🧠","Modelo","Procesa y genera"],["📥","Respuesta","Vuelve a tu flujo"]],"cap":"Una llamada a la API: te autenticas con tu clave, envías la petición, el modelo genera y la respuesta vuelve a tu flujo.","narr":"Veamos esa llamada por dentro. Primero te autenticas con una clave, que dice quién eres y habilita el cobro. Luego mandas la petición con tu instrucción. El modelo la procesa y genera el resultado. Y la respuesta vuelve a tu flujo, lista para el siguiente paso. En Make o n8n esto es un solo nodo."},{"type":"myth","dur":17,"eyeb":"A tener en cuenta","h2":"Tres cosas para no equivocarte al elegir","myths":[["La más cara no es la mejor",", la mejor es la que resuelve tu tarea"],["No cases tu flujo con un solo proveedor",", deja espacio para cambiar"],["El modelo no cuida tus datos por ti",", eso lo decides tú"]],"cap":"La más cara no siempre gana. No dependas de un solo proveedor. Y la privacidad de tus datos la decides tú.","narr":"Antes de cerrar, tres advertencias honestas. La herramienta más cara no es siempre la mejor: la mejor es la que resuelve tu tarea al menor costo razonable. No cases tu flujo con un solo proveedor: deja espacio para cambiar cuando salga algo mejor. Y recuerda que la privacidad de tus datos la decides tú, no el modelo."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Elegir bien vale más que usar la herramienta de moda","sub":"Ya tienes el mapa y los criterios. Sigue: conectar tu primera API y verla trabajar.","cap":"Con el mapa de modelos y los tres criterios, ya eliges con criterio. Sigue: conectar tu primera API.","narr":"Recapitulemos. Los modelos se agrupan por lo que producen, eliges equilibrando coste, calidad y privacidad, y los conectas a tus flujos mediante una API. Elegir con criterio vale más que usar la herramienta de moda. Ahora sigue lo práctico: conectar tu primera API y verla trabajar. Nos vemos ahí."}],"5":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Ya entiendes los flujos: ahora vas a construirlos","sub":"n8n es el lienzo donde conectas bloques y armas agentes reales, sin escribir código.","cap":"n8n es la herramienta donde conectas bloques y construyes flujos y agentes reales, sin programar.","narr":"Bienvenido a esta lección. Ya sabes qué es un flujo y de qué piezas está hecho. Ahora toca lo bueno: construirlo con tus manos. La herramienta se llama n8n, un lienzo donde conectas bloques y armas agentes reales, sin escribir código."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro cosas, paso a paso","items":[["1","Qué es n8n","y cómo lo pones a andar"],["2","Tu primer flujo","trigger, lógica y acción"],["3","El nodo AI Agent","cómo le sumas inteligencia"]],"cap":"En esta lección: qué es n8n, cómo armar tu primer flujo, y cómo integrar el nodo de IA.","narr":"En los próximos minutos vas a entender cuatro cosas: qué es n8n y cómo lo pones en marcha, cómo se arma tu primer flujo de principio a fin, cómo le sumas un agente de inteligencia artificial, y cómo lo dejas corriendo sin sorpresas."},{"type":"define","dur":15,"eyeb":"El concepto base","h2":"Primero, qué es n8n","def":"<b>n8n</b> es una plataforma visual donde arrastras y conectas <b>nodos</b>. Cada nodo hace una cosa, y el flujo pasa de uno al siguiente.","cap":"n8n es una plataforma visual de nodos: cada nodo hace una cosa y el flujo pasa de uno al siguiente.","narr":"Empecemos por la base. n8n es una plataforma visual donde arrastras bloques, llamados nodos, y los conectas con una línea. Cada nodo hace una sola cosa: leer datos, decidir, enviar algo. El flujo pasa de un nodo al siguiente, en orden. Eso es todo."},{"type":"compare","dur":18,"eyeb":"La primera decisión","h2":"En la nube o en tu propio servidor","colA":["n8n Cloud","Listo en minutos","Te registras y empiezas. Ellos se encargan del servidor. Ideal para arrancar y aprender rápido."],"colB":["Self-hosted","Tú lo controlas","Lo instalas en tu propio servidor. Más control y privacidad de datos, a cambio de más trabajo de mantenimiento."],"cap":"n8n Cloud: listo en minutos, ellos manejan el servidor. Self-hosted: más control y privacidad, más mantenimiento.","narr":"Lo primero que vas a decidir es dónde corre n8n. En la nube, te registras y empiezas en minutos: ellos manejan el servidor. O en tu propio servidor, lo que llaman self-hosted: más control y más privacidad de tus datos, a cambio de encargarte del mantenimiento. Para aprender, la nube es el camino más corto."},{"type":"pieces","dur":16,"eyeb":"El vocabulario","h2":"Cuatro palabras que vas a usar todo el tiempo","pieces":[["🧩","Nodo","Un paso del flujo"],["⚡","Trigger","El nodo que arranca todo"],["🔑","Credencial","Tu acceso a otra app"],["▶️","Ejecución","Una corrida del flujo"]],"cap":"Nodo = un paso. Trigger = el que arranca. Credencial = tu acceso a una app. Ejecución = una corrida del flujo.","narr":"Cuatro palabras te van a acompañar siempre en n8n. Nodo: cada paso del flujo. Trigger: el nodo especial que lo pone en marcha, el detonante que ya conoces. Credencial: el acceso guardado a otra app, como tu correo o una base. Y ejecución: cada vez que el flujo corre de principio a fin. Con estas cuatro te mueves con soltura."},{"type":"flow","dur":18,"eyeb":"Tu primer flujo","h2":"Trigger, lógica y acción: la estructura base","nodes":[["⚡","Trigger","Algo lo dispara"],["🔀","Lógica","IF o Switch decide"],["🌐","Acción","HTTP o app externa"],["✅","Resultado","Queda hecho"]],"cap":"Todo flujo sigue la misma estructura: un trigger lo dispara, la lógica decide, una acción ejecuta y entrega el resultado.","narr":"Todo primer flujo sigue la misma columna vertebral. Un trigger lo dispara: por ejemplo, un webhook que recibe un aviso. Un nodo de lógica decide el camino, con un IF o un Switch. Un nodo de acción ejecuta, como un HTTP Request que llama a otra app. Y el resultado queda hecho. Esa estructura se repite en casi todo lo que vas a construir."},{"type":"spot","dur":16,"snum":"El corazón de los datos","sic":"🔗","stitle":"Cada nodo recibe lo del anterior","stext":"Los datos viajan en JSON de un nodo al siguiente. Un nodo usa lo que produjo el que va antes.","sex":"nodo 1 produce · nodo 2 lo usa · y así sigue","cap":"Los datos viajan en JSON de un nodo al siguiente: cada nodo trabaja con lo que produjo el anterior.","narr":"Aquí está la idea que hace clic con todo. Los datos viajan de un nodo al siguiente en un formato llamado JSON. Cada nodo recibe lo que produjo el anterior y trabaja con eso. El trigger trae la información, el siguiente nodo la transforma, el que sigue la usa. Si entiendes ese hilo, entiendes cómo piensa n8n por dentro."},{"type":"define","dur":15,"eyeb":"La pieza estrella","h2":"El nodo que lo cambia todo: AI Agent","def":"El nodo <b>AI Agent</b> mete un agente de IA dentro de tu flujo. Le das un objetivo y herramientas, y él decide los pasos.","cap":"El nodo AI Agent mete un agente de IA en tu flujo: le das objetivo y herramientas, y él decide los pasos.","narr":"Y llegamos a la pieza estrella. n8n tiene un nodo llamado AI Agent, que mete un agente de inteligencia artificial dentro de tu flujo. En lugar de programar cada decisión, le das un objetivo y unas herramientas. El agente decide por su cuenta qué pasos dar para cumplirlo. Aquí es donde el criterio entra a tu automatización."},{"type":"pieces","dur":17,"eyeb":"Cómo se arma el agente","h2":"Al nodo AI Agent le conectas tres cosas","pieces":[["🧠","Modelo","El LLM que razona"],["📇","Memoria","Recuerda la conversación"],["🔧","Tools","Con qué puede actuar"]],"cap":"Al nodo AI Agent le conectas un modelo (razona), memoria (recuerda) y tools (con qué actúa).","narr":"Armar ese agente es más simple de lo que parece. Al nodo AI Agent le conectas tres piezas, las mismas que ya viste. Un modelo, el LLM que razona y decide. Una memoria, para que recuerde lo hablado. Y las tools, las herramientas con las que puede actuar: buscar en tus datos, enviar un mensaje, consultar una API. Tres conexiones, y tienes un agente funcionando."},{"type":"flow","dur":18,"eyeb":"Un ejemplo completo","h2":"Un agente que atiende consultas por webhook","nodes":[["💬","Trigger","Llega una consulta"],["🧠","AI Agent","Razona con tools"],["🔧","Tool","Busca en tu base"],["📤","Respuesta","Contesta al cliente"]],"cap":"Ejemplo: un webhook recibe la consulta, el AI Agent razona, usa una tool para buscar en tu base y responde.","narr":"Juntemos todo en un caso real. Un cliente manda una consulta y un webhook la recibe: ese es el trigger. El nodo AI Agent la lee y razona qué necesita. Usa una tool para buscar la respuesta en tu base de datos. Y con eso redacta y contesta. Un flujo corto, pero es un agente completo trabajando solo."},{"type":"list","dur":17,"eyeb":"Antes de producción","h2":"Un flujo que corre solo tiene que aguantar fallos","items":[["🔁","Reintentos","Si un paso falla, que lo intente de nuevo"],["🚨","Error workflow","Un flujo aparte que te avisa cuando algo truena"],["👁️","Ejecuciones","Revisa el historial para ver qué pasó"]],"cap":"Para producción: configura reintentos, un workflow de error que avise, y revisa el historial de ejecuciones.","narr":"Antes de dejarlo corriendo solo, un flujo serio tiene que aguantar fallos. Configura reintentos, para que un paso que falla lo intente de nuevo antes de rendirse. Arma un workflow de error, un flujo aparte que te avisa cuando algo truena. Y revisa el historial de ejecuciones, donde n8n guarda qué pasó en cada corrida. Eso separa un experimento de algo confiable."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas honestas antes de lanzarte","myths":[["No es magia sin errores",", vas a depurar y ajustar"],["No lo dejes sin vigilar",", revisa sus ejecuciones"],["No automatices el caos",", primero el proceso claro"]],"cap":"n8n no elimina los errores: vas a depurar. No lo dejes sin vigilar. Y primero ordena el proceso.","narr":"Un punto honesto antes de lanzarte. n8n no es magia sin errores: vas a probar, fallar y ajustar, y eso es normal. No lo dejes funcionando sin mirar: revisa sus ejecuciones, sobre todo al inicio. Y no automatices el desorden: si el proceso no está claro en tu cabeza, tampoco lo estará en el lienzo. La herramienta potencia tu criterio, no lo reemplaza."},{"type":"chips","dur":15,"eyeb":"Lo que ya tienes","h2":"Con esto ya puedes armar tu primer agente","chips":[["⚡","Trigger"],["🔀","Lógica"],["🌐","Acción"],["🧠","AI Agent"],["🔁","Errores"]],"cap":"Ya tienes las piezas: trigger, lógica, acción, el nodo AI Agent y el manejo de errores.","narr":"Recapitulemos lo que ya llevas. Sabes qué es n8n y dónde corre. Conoces el trigger, la lógica y la acción. Sabes armar el nodo AI Agent con su modelo, memoria y tools. Y sabes prepararlo para producción con reintentos y avisos. Son todas las piezas de tu primer agente."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"n8n es donde tu criterio se vuelve un flujo que corre solo","sub":"Ya conoces las piezas. Sigue lo mejor: abrir n8n y construir tu primer agente paso a paso.","cap":"n8n convierte tu criterio en un flujo que corre solo. Sigue: abrirlo y construir tu primer agente.","narr":"Eso es n8n. No es solo una herramienta bonita: es donde tu criterio se convierte en un flujo que corre solo, una y otra vez, sin ti en el medio. Ya conoces las piezas. Ahora sigue lo mejor: abrir n8n y construir tu primer agente, paso a paso. Nos vemos en la práctica."}],"6":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Make convierte una idea en un flujo que ves moverse","sub":"Su editor visual muestra los datos viajando de un módulo al siguiente, en vivo.","cap":"Make es una herramienta visual donde armas automatizaciones conectando módulos y ves los datos moverse entre ellos.","narr":"Bienvenido a esta lección. Make es una herramienta para armar automatizaciones sin programar. Su gracia es visual: conectas módulos con líneas y ves los datos viajar de uno al siguiente. En los próximos minutos vas a entender cómo piensa Make y cuándo conviene usarlo."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro ideas, en pocos minutos","items":[["1","Make frente a n8n","cuándo conviene cada uno"],["2","Escenarios y módulos","cómo viajan los datos"],["3","Routers, filtros e iteradores","para ramificar y recorrer"]],"cap":"En esta lección: Make frente a n8n, cómo fluyen los datos entre módulos, y cómo ramificar y recorrer colecciones.","narr":"Vas a entender cuatro cosas: en qué se diferencia Make de n8n y cuándo elegir cada uno, cómo se arma un escenario y viajan los datos, cómo ramificar y recorrer listas, y cómo sumarle inteligencia artificial cuidando el consumo."},{"type":"define","dur":15,"eyeb":"El concepto base","h2":"Primero, qué es un escenario","def":"Un <b>escenario</b> en Make es tu automatización completa: una cadena de <b>módulos</b> conectados que se ejecutan en orden cuando algo la dispara.","cap":"Un escenario es la automatización completa: módulos conectados que se ejecutan en orden al dispararse.","narr":"Empecemos por la palabra clave. En Make, tu automatización entera se llama escenario. Es una cadena de módulos conectados que se ejecutan en orden cuando algo la dispara. Cada módulo hace una cosa, y el escenario es la película completa."},{"type":"pieces","dur":16,"eyeb":"La anatomía","h2":"Todo escenario se arma con estas piezas","pieces":[["▶️","Disparador","El primer módulo"],["🧩","Módulo","Una acción o app"],["📦","Bundle","Un paquete de datos"],["🔗","Conexión","La línea que los une"]],"cap":"Escenario = disparador (arranca) + módulos (cada acción) + bundles (los datos que pasan) + conexiones (las líneas).","narr":"Un escenario tiene cuatro piezas. El disparador, el primer módulo que lo pone en marcha. Los módulos, cada uno una acción o una app. Los bundles, los paquetes de datos que pasan de un módulo al siguiente. Y las conexiones, las líneas que los unen. Reconoce estas cuatro y lees cualquier escenario."},{"type":"compare","dur":18,"eyeb":"La decisión práctica","h2":"Make y n8n resuelven lo mismo, distinto","colA":["Make","Visual y guiado","Editor muy intuitivo y cientos de apps listas. Cobra por operación: cada acción de cada módulo cuenta."],"colB":["n8n","Flexible y técnico","Más control, self-hosting y nodos de código. Cobra por ejecución, no por paso: sale mejor a gran volumen."],"cap":"Make: más visual y guiado, cobra por operación. n8n: más flexible y técnico, cobra por ejecución; conviene a gran volumen.","narr":"¿Make o n8n? Los dos conectan apps y suman inteligencia artificial. Make es más visual y guiado, con cientos de apps listas, y cobra por operación: cada paso cuenta. n8n da más control, permite alojarlo tú mismo y escribir código, y cobra por ejecución. Para empezar rápido, Make. Para gran volumen o control fino, n8n."},{"type":"define","dur":15,"eyeb":"La unidad que se paga","h2":"La palabra que decide tu factura: operación","def":"Una <b>operación</b> es cada vez que un módulo hace su trabajo. Tu plan trae un número de operaciones al mes: menos módulos y menos vueltas, menos consumo.","cap":"Una operación es cada vez que un módulo actúa. Tu plan incluye un tope mensual, así que el diseño afecta el costo.","narr":"Antes de seguir, una palabra que impacta tu bolsillo: operación. Cada vez que un módulo hace su trabajo, cuenta una operación. Tu plan trae un tope mensual. Por eso el diseño importa: cuantos más módulos y más vueltas, más operaciones consumes. Diseñar con cabeza es diseñar barato."},{"type":"flow","dur":18,"eyeb":"Un escenario completo","h2":"Un pedido nuevo, de principio a fin","nodes":[["🛒","Disparador","Entra un pedido"],["📇","Busca","Datos del cliente"],["🤖","IA","Redacta el aviso"],["📧","Actúa","Envía y registra"]],"cap":"Ejemplo: entra un pedido (disparador), se buscan los datos del cliente, la IA redacta el aviso y otro módulo lo envía y registra.","narr":"Veámoslo junto. Entra un pedido nuevo: ese es el disparador. Un módulo busca los datos del cliente. Otro, con inteligencia artificial, redacta un aviso claro. Y el último lo envía y lo registra en tu planilla. Cuatro módulos conectados, un proceso entero resuelto sin que toques nada."},{"type":"pieces","dur":17,"eyeb":"Las herramientas de control","h2":"Tres piezas para que el flujo decida y recorra","pieces":[["🔀","Router","Parte el flujo en rutas"],["🔎","Filtro","Deja pasar solo lo que cumple"],["🔁","Iterador","Recorre uno por uno"]],"cap":"Router: divide el flujo en rutas. Filtro: deja pasar solo lo que cumple una condición. Iterador: recorre una lista uno por uno.","narr":"Un escenario no siempre es una línea recta. Tres piezas le dan lógica. El router parte el flujo en varias rutas. El filtro pone una condición y deja pasar solo lo que la cumple. Y el iterador toma una lista y la recorre elemento por elemento. Con estas tres, tu escenario decide y procesa en volumen."},{"type":"spot","dur":16,"snum":"Router más filtro","sic":"🔀","stitle":"Ramificar con criterio","stext":"El router abre caminos y cada ruta lleva su filtro: cada dato sigue solo el camino que le corresponde.","sex":"pedido grande → una ruta · pedido chico → otra","cap":"El router abre varios caminos y cada ruta puede llevar un filtro, para que cada dato siga la ruta que le corresponde.","narr":"Router y filtro trabajan juntos y valen oro. El router abre varios caminos, y en cada ruta pones un filtro con su condición. Así, un pedido grande sigue una ruta, uno chico sigue otra, y una queja va directa a una persona. Cada dato toma solo el camino que le corresponde, sin que escribas una sola línea de código."},{"type":"spot","dur":16,"snum":"El iterador","sic":"🔁","stitle":"Cuando llegan muchos a la vez","stext":"Si un módulo trae una lista, el iterador la parte en elementos sueltos y el resto del flujo actúa sobre cada uno.","sex":"10 facturas en un correo → procesar una por una","cap":"Si un módulo devuelve una lista, el iterador la separa en elementos sueltos para tratar cada uno por su cuenta.","narr":"El iterador resuelve algo muy común. A veces un módulo trae una lista entera: diez facturas en un correo, varias filas de una tabla. El iterador parte esa lista en elementos sueltos, y el resto del flujo actúa sobre cada uno por separado. Eso sí, recuerda: cada vuelta consume operaciones, así que úsalo con intención."},{"type":"list","dur":16,"eyeb":"IA y control de consumo","h2":"Sumar inteligencia sin dispararte la factura","items":[["🧠","Módulo de IA","Un paso más que resume o redacta"],["🔎","Filtra antes","Que la IA solo procese lo que vale"],["🧯","Maneja errores","Reintenta o desvía en vez de romper"]],"cap":"Integra IA como un módulo más, filtra antes para no procesar de más, y agrega manejo de errores para que un fallo no rompa todo.","narr":"Sumar inteligencia artificial en Make es agregar un módulo más que resume, clasifica o redacta. Dos consejos para no dispararte la factura ni los problemas. Filtra antes: que la IA procese solo lo que de verdad vale la pena. Y maneja los errores: agrega rutas que reintenten o desvíen, para que un fallo no rompa el escenario entero."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas para no llevarte una sorpresa","myths":[["No es gratis a escala",", cada operación se cuenta"],["Más módulos no es mejor",", suma costo y puntos de falla"],["La IA no se deja sola",", revisa lo que decide"]],"cap":"A escala cada operación cuenta; más módulos suman costo y fallas; y la IA necesita tu revisión en lo que importa.","narr":"Antes de cerrar, tres advertencias sanas. Make no es gratis a escala: cada operación se cuenta, y un escenario descuidado se vuelve caro. Más módulos no siempre es mejor: suman costo y más puntos donde algo puede fallar. Y la inteligencia artificial no se deja sola: revisa lo que decide en lo que de verdad importa."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Un escenario es criterio ordenado en módulos que ves moverse","sub":"Ya sabes cómo piensa Make. Sigue: armar tu primer escenario y verlo correr paso a paso.","cap":"Un escenario es criterio ordenado en módulos. Ya sabes cómo piensa Make; sigue armar el tuyo y verlo correr.","narr":"Recapitulemos. En Make, un escenario es una cadena de módulos por la que viajan datos. Los routers, filtros e iteradores le dan lógica. Y todo cuesta operaciones, así que diseñas con cabeza. Ya sabes cómo piensa Make. Ahora sigue lo mejor: armar tu primer escenario y verlo correr. Nos vemos en la práctica."}],"7":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Ahora puedes construir software describiendo lo que quieres","sub":"Claude escribe y corrige el código; tú pones la intención y el criterio.","cap":"Con Claude puedes crear automatizaciones y software describiendo lo que necesitas, sin ser programador experto.","narr":"Bienvenido a esta lección. Durante años, automatizar de verdad exigía saber programar. Eso cambió. Hoy puedes describir lo que quieres en tu idioma y Claude escribe el código por ti. A eso se le llama vibe coding, y aquí vas a entender cómo se hace bien."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro ideas, en pocos minutos","items":[["1","Qué es el vibe coding","y cuándo conviene usarlo"],["2","Claude como copiloto","para generar y corregir código"],["3","Qué es MCP","cómo conectar Claude a tus herramientas"]],"cap":"En esta lección: qué es el vibe coding, Claude como copiloto de automatización, y cómo conectarlo a tus herramientas con MCP.","narr":"Vas a entender cuatro cosas: qué es el vibe coding y cuándo funciona, cómo usar a Claude de copiloto para generar y corregir código, qué es el protocolo MCP para conectarlo a tus herramientas, y cómo se ve todo esto en un proyecto real."},{"type":"define","dur":16,"eyeb":"El concepto base","h2":"Primero, qué es el vibe coding","def":"El <b>vibe coding</b> es construir software describiendo tu intención en <b>lenguaje natural</b>: tú dices qué quieres lograr y la IA escribe el código que lo hace.","cap":"Vibe coding es construir describiendo tu intención en lenguaje natural: tú dices el qué, la IA escribe el cómo.","narr":"Empecemos por la base. El vibe coding es construir software describiendo tu intención en lenguaje natural. Tú explicas qué quieres lograr, con tus palabras, y la inteligencia artificial traduce esa idea a código que funciona. Tú pones el qué; ella resuelve el cómo."},{"type":"compare","dur":18,"eyeb":"La distinción clave","h2":"No es lo mismo escribir código que dirigirlo","colA":["Programar a mano","Tú escribes cada línea","Necesitas dominar la sintaxis y recordar cada detalle. Avanzas al ritmo de lo que ya sabes."],"colB":["Vibe coding","Tú diriges, la IA escribe","Describes la meta y revisas el resultado. Avanzas más rápido, pero tu criterio sigue mandando."],"cap":"Programar a mano: escribes cada línea. Vibe coding: describes la meta, revisas el resultado y tu criterio manda.","narr":"Aquí está la diferencia. Programar a mano es escribir cada línea tú mismo: avanzas al ritmo de lo que ya dominas. En el vibe coding tú diriges y la IA escribe: describes la meta, revisas lo que entrega y corriges el rumbo. Vas más rápido, pero tu criterio sigue al mando. Ese matiz lo es todo."},{"type":"spot","dur":16,"snum":"La regla de oro","sic":"🔍","stitle":"Genera rápido, pero revisa siempre","stext":"Claude puede equivocarse con total seguridad. Tú lees, pruebas y validas lo que entrega antes de confiar en ello.","sex":"describe · genera · prueba · valida","cap":"Claude puede equivocarse con seguridad. Genera rápido, pero tú siempre lees, pruebas y validas antes de confiar.","narr":"Y aquí la regla de oro del vibe coding disciplinado. Claude escribe rápido, pero puede equivocarse con total seguridad. Por eso el ciclo es: describe, genera, prueba y valida. Nunca uses en producción algo que no probaste. La IA acelera tu trabajo; tu revisión evita que ese código te falle."},{"type":"list","dur":16,"eyeb":"Cuándo funciona","h2":"Brilla aquí, y conviene evitarlo allá","items":[["✅","Prototipos y scripts","Probar una idea o resolver una tarea puntual"],["🔗","Integraciones y datos","Conectar servicios, transformar y limpiar información"],["⚠️","Sistemas críticos","Ahí exige revisión experta, no confíes a ciegas"]],"cap":"Brilla en prototipos, scripts e integraciones. En sistemas críticos exige revisión experta: no confíes a ciegas.","narr":"¿Cuándo conviene? Brilla en prototipos y scripts, para probar una idea o resolver una tarea puntual. También en integraciones y manejo de datos, conectando servicios y limpiando información. ¿Dónde tener cuidado? En sistemas críticos, donde un error cuesta caro: ahí el código de la IA necesita revisión experta antes de confiar."},{"type":"pieces","dur":16,"eyeb":"Claude como copiloto","h2":"Cuatro tareas donde te ahorra horas","pieces":[["✍️","Genera","Escribe el script desde tu idea"],["🐞","Depura","Encuentra y corrige errores"],["🔄","Transforma","Convierte y limpia datos"],["💡","Explica","Te dice qué hace cada parte"]],"cap":"Claude copiloto: genera scripts, depura errores, transforma datos y te explica qué hace cada parte del código.","narr":"Como copiloto, Claude te sirve en cuatro frentes. Genera: escribe un script partiendo de tu idea. Depura: le pegas un error y te dice cómo corregirlo. Transforma: convierte y limpia datos entre formatos. Y explica: te aclara qué hace cada parte, para que aprendas mientras construyes. Cuatro tareas, muchas horas ahorradas."},{"type":"flow","dur":18,"eyeb":"Cómo trabajas con él","h2":"El ciclo de construir con Claude, paso a paso","nodes":[["🗣️","Describe","Explicas la tarea"],["⚙️","Genera","Claude escribe"],["▶️","Prueba","Corres y revisas"],["🔁","Ajusta","Corriges e iteras"]],"cap":"El ciclo: describes la tarea, Claude genera, tú pruebas el resultado y ajustas iterando hasta que funcione.","narr":"Trabajar con Claude es un ciclo simple que se repite. Describes la tarea con claridad. Claude genera el código. Tú lo corres y revisas si hace lo que esperabas. Y ajustas: le pides un cambio, corriges un detalle, e iteras. Cuanto más claro describes, menos vueltas necesitas. La claridad es tu mejor herramienta."},{"type":"define","dur":16,"eyeb":"Conectar Claude al mundo","h2":"Qué es MCP","def":"El <b>MCP</b> es un protocolo que le da a Claude <b>herramientas</b>: le permite leer tus archivos, consultar APIs y usar servicios, no solo conversar.","cap":"MCP es un protocolo que conecta Claude a herramientas: archivos, APIs y servicios. Deja de solo conversar y actúa.","narr":"Hasta aquí Claude solo escribe texto y código. Para que actúe en tu mundo existe el MCP, el protocolo de contexto de modelo. Es un estándar que le da herramientas: leer tus archivos, consultar una API, usar un servicio. Con MCP, Claude deja de solo conversar y empieza a hacer cosas por ti."},{"type":"flow","dur":17,"eyeb":"MCP en acción","h2":"De una petición tuya a una acción real","nodes":[["🗣️","Pides","Ordena esta carpeta"],["🧠","Razona","Claude decide qué hacer"],["🔧","Usa la tool","Lee y mueve archivos"],["✅","Resuelve","Carpeta ordenada"]],"cap":"Con MCP: le pides ordenar una carpeta, Claude razona, usa la herramienta para leer y mover archivos, y lo resuelve.","narr":"Veámoslo en acción. Le pides a Claude: ordena esta carpeta. Con MCP, razona qué hacer, usa una herramienta para leer los archivos y moverlos donde corresponde, y te devuelve la carpeta ordenada. No describió los pasos: los ejecutó. Ese salto, de hablar a actuar, es lo que hace tan potente al MCP."},{"type":"chips","dur":15,"eyeb":"A qué se conecta","h2":"Con MCP, Claude alcanza tus herramientas","chips":[["📁","Archivos"],["🌐","APIs"],["🗄️","Bases de datos"],["💬","Slack"],["➕","y más"]],"cap":"Mediante MCP, Claude se conecta a tus archivos, APIs, bases de datos y apps como Slack, entre muchas otras.","narr":"¿A qué se conecta? A tus archivos locales, a las APIs de los servicios que ya usas, a bases de datos, a apps como Slack, y a muchas más cada mes. La idea es sencilla: en lugar de copiar y pegar entre sistemas, Claude los alcanza directo y trabaja con ellos por ti."},{"type":"flow","dur":18,"eyeb":"Proyecto guiado","h2":"Automatizar una tarea real, de la idea al flujo","nodes":[["💡","Idea","Reporte diario de ventas"],["📝","Describe","Se lo explicas a Claude"],["⚙️","Construye","Genera el script y lo conecta"],["🚀","Corre","Se ejecuta solo cada día"]],"cap":"Proyecto: partes de una idea, se la describes a Claude, él construye y conecta el script, y termina corriendo solo.","narr":"Juntemos todo en un proyecto real. Idea: quieres un reporte de ventas cada mañana. Se lo describes a Claude con detalle. Él construye el script, lo conecta a tus datos vía MCP y lo prueba contigo. Al final, el reporte se genera solo cada día. De una idea en tu cabeza a un flujo funcionando, iterando paso a paso."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas para no llevarte una sorpresa","myths":[["No te vuelve programador senior",", te da un copiloto que hay que dirigir"],["No siempre acierta",", su código se prueba antes de usar"],["No entiende tu negocio",", el criterio y el contexto los pones tú"]],"cap":"El vibe coding no te vuelve senior ni acierta siempre: su código se prueba. Y no entiende tu negocio: eso lo pones tú.","narr":"Antes de cerrar, tres advertencias honestas. El vibe coding no te convierte en programador senior de un día para otro: te da un copiloto que hay que saber dirigir. No siempre acierta, así que su código se prueba antes de usarlo. Y no entiende tu negocio: el contexto y el criterio los sigues poniendo tú. Bien usado, multiplica lo que puedes construir."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Describes la intención; Claude escribe, tú validas","sub":"Ya sabes qué es el vibe coding y cómo conectar Claude con MCP. Sigue: construirlo tú mismo.","cap":"Vibe coding: tú describes la intención, Claude escribe y tú validas. Con MCP, además actúa. Sigue: practicarlo.","narr":"Recapitulemos. El vibe coding es construir describiendo tu intención: Claude escribe el código y tú lo validas. Con MCP, además, se conecta a tus herramientas y actúa. Ya tienes el mapa completo. Ahora sigue lo mejor: sentarte a construir tu primera automatización con él. Nos vemos en la práctica."}],"8":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Antes de automatizar, hay que entender el proceso de verdad","sub":"El error más caro no es elegir mal la herramienta: es automatizar un proceso que nadie entendió bien.","cap":"El error más caro no es la herramienta, sino automatizar un proceso que nadie entendió bien. Empecemos por entenderlo.","narr":"Bienvenido a esta lección. El error más caro en automatización no es elegir mal la herramienta. Es automatizar un proceso que nadie entendió del todo. Antes de tocar nada, hay que levantar el proceso real y detectar dónde conviene actuar. Eso vamos a aprender."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro pasos, en pocos minutos","items":[["1","Levantar el proceso real","con entrevistas y observación"],["2","Encontrar los cuellos de botella","con datos, no con intuición"],["3","Priorizar qué automatizar","impacto contra complejidad"]],"cap":"En esta lección: levantar el proceso real, encontrar cuellos de botella con datos y priorizar qué automatizar primero.","narr":"Vas a aprender cuatro pasos. Levantar el proceso real como de verdad ocurre. Encontrar los cuellos de botella con datos, no con corazonadas. Priorizar qué automatizar primero. Y convertir ese hallazgo en una propuesta que la dirección apruebe."},{"type":"compare","dur":18,"eyeb":"La distinción clave","h2":"El proceso documentado no es el proceso real","colA":["AS-IS documentado","Lo que dice el manual","El diagrama oficial: pasos limpios, ordenados, como debería funcionar en teoría."],"colB":["AS-IS real","Lo que la gente hace","Los atajos, los reprocesos y el Excel paralelo que nadie anotó, pero que sostienen el día a día."],"cap":"El proceso documentado es la teoría limpia. El real incluye atajos, reprocesos y Excels paralelos. Automatizas el real.","narr":"Aquí está la distinción que más importa. El proceso documentado es la teoría: pasos limpios, como debería funcionar. El proceso real es otra cosa: los atajos, los reprocesos, el Excel paralelo que nadie anotó. Tú vas a automatizar el real, así que a ese tienes que descubrirlo."},{"type":"pieces","dur":16,"eyeb":"Cómo levantar el proceso","h2":"Tres técnicas que se complementan","pieces":[["🎤","Entrevista","Preguntas al que lo hace"],["👀","Observación","Miras cómo trabaja"],["📄","Evidencia","Revisas los documentos"]],"cap":"Para levantar bien un proceso: entrevistas a quien lo ejecuta, observas cómo trabaja y revisas la evidencia real.","narr":"Para levantar un proceso usas tres técnicas que se complementan. La entrevista: le preguntas a quien lo ejecuta cada día. La observación: te sientas al lado y miras cómo trabaja de verdad. Y la evidencia: revisas los archivos, correos y planillas que deja el proceso. Ninguna sola alcanza; juntas te dan la foto completa."},{"type":"spot","dur":16,"snum":"El error más común","sic":"🗣️","stitle":"Preguntar mal en la entrevista","stext":"Si preguntas cómo debería hacerse, te describen el manual. Pregunta cómo lo hiciste hoy, con el último caso concreto.","sex":"¿Qué hiciste con el último pedido que entró?","cap":"No preguntes cómo debería hacerse: te recitan el manual. Pregunta por el último caso concreto que resolvieron.","narr":"Cuidado con un error muy común. Si preguntas cómo debería hacerse, te describen el manual, no la realidad. En vez de eso, pregunta por el último caso concreto: qué hiciste con el último pedido que entró hoy. Con casos reales aparecen los atajos y las excepciones que nunca están en el diagrama."},{"type":"define","dur":15,"eyeb":"Cuando hay datos","h2":"Otra vía: el process mining","def":"El <b>process mining</b> reconstruye el proceso real a partir de los <b>registros que dejan tus sistemas</b> — quién hizo qué, cuándo y en qué orden.","cap":"El process mining reconstruye el proceso real a partir de los registros que dejan tus sistemas: quién hizo qué y cuándo.","narr":"Cuando el proceso vive en sistemas, hay otra vía muy potente: el process mining. En lugar de preguntar, reconstruye el proceso a partir de los registros que esos sistemas ya guardan: quién hizo qué, cuándo, y en qué orden. Los datos no maquillan la realidad como a veces lo hacen las personas."},{"type":"flow","dur":17,"eyeb":"Dónde mirar","h2":"Los cuellos de botella dejan huella","nodes":[["⏳","Esperas","Tareas que se estancan"],["🔁","Reprocesos","Lo que se rehace"],["✋","Traspasos","De una mano a otra"],["🐢","Manual","Lo lento y repetitivo"]],"cap":"Los cuellos de botella se ven en esperas largas, reprocesos, traspasos entre personas y pasos manuales lentos.","narr":"¿Dónde están los cuellos de botella? Dejan huella en cuatro lugares. Las esperas, donde una tarea se estanca por días. Los reprocesos, lo que se rehace por errores. Los traspasos, cada vez que el trabajo pasa de una mano a otra. Y lo manual, esos pasos lentos y repetitivos. Ahí es donde vale la pena mirar."},{"type":"define","dur":15,"eyeb":"El criterio del consultor","h2":"No todo lo molesto se debe automatizar","def":"Prioriza cruzando dos ejes: el <b>impacto</b> que genera resolverlo y la <b>complejidad</b> de automatizarlo. Lo demás es opinión.","cap":"Prioriza cruzando dos ejes: cuánto impacto genera resolverlo y qué tan complejo es automatizarlo.","narr":"Ahora, con la lista de oportunidades, aparece la tentación de automatizar lo que más molesta. Pero no todo lo molesto conviene. El criterio del consultor es cruzar dos ejes: el impacto que genera resolver algo, y la complejidad de automatizarlo. Todo lo demás es opinión."},{"type":"compare","dur":18,"eyeb":"La matriz de priorización","h2":"Por dónde empezar y qué dejar para después","colA":["Quick wins","Alto impacto, baja complejidad","Empieza por aquí. Resultado visible, esfuerzo bajo: así ganas confianza y presupuesto."],"colB":["Grandes proyectos","Alto impacto, alta complejidad","Valen la pena, pero planifícalos. No arranques por lo más difícil y largo."],"cap":"Empieza por los quick wins: alto impacto y baja complejidad. Los proyectos grandes valen, pero se planifican aparte.","narr":"Al cruzar esos ejes aparece el orden. Arriba a un lado, los quick wins: mucho impacto, poca complejidad. Empieza siempre por ahí, porque das un resultado visible con poco esfuerzo y ganas confianza. Los grandes proyectos, de alto impacto pero difíciles, valen la pena, pero se planifican aparte. No arranques por lo más largo."},{"type":"flow","dur":17,"eyeb":"El paso final","h2":"Del hallazgo al caso de negocio","nodes":[["🔍","Hallazgo","La oportunidad detectada"],["📐","Medición","Horas y errores hoy"],["💰","ROI","Ahorro contra costo"],["📊","Propuesta","Defendible ante la dirección"]],"cap":"Una oportunidad se vuelve propuesta midiendo horas y errores actuales, calculando el ROI y presentándolo con números.","narr":"El último paso convierte el hallazgo en una propuesta. Tomas la oportunidad detectada. Mides cuánto cuesta hoy: horas y errores. Calculas el retorno: cuánto ahorras contra lo que cuesta automatizarlo. Y lo presentas con números. Una oportunidad con ROI defendible se aprueba; una intuición, no."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas para no equivocarte","myths":[["El process mining no reemplaza hablar",", los datos dicen qué, la gente dice por qué"],["Más automatizable no es más prioritario",", primero mide el impacto"],["La IA no decide qué automatizar",", ordena tus datos, decides tú"]],"cap":"Los datos dicen qué pasa; la gente, por qué. Lo fácil no es lo prioritario. Y la IA ordena, pero decides tú.","narr":"Antes de cerrar, tres advertencias sanas. El process mining no reemplaza hablar con la gente: los datos te dicen qué pasa, las personas te dicen por qué. Que algo sea fácil de automatizar no lo hace prioritario: primero mide el impacto. Y la inteligencia artificial puede ordenar y resumir tus hallazgos, pero la decisión de qué automatizar es tuya."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Primero entiendes el proceso, después lo automatizas","sub":"Ya sabes levantar, medir y priorizar. En la práctica vas a armar tu propio pipeline de oportunidades.","cap":"Levantas el proceso real, mides con datos y priorizas por impacto. Sigue: armar tu pipeline de oportunidades.","narr":"Recapitulemos. Levantas el proceso real con entrevistas, observación y datos. Encuentras los cuellos de botella. Priorizas cruzando impacto y complejidad. Y conviertes el hallazgo en un caso de negocio con números. Primero entiendes, después automatizas. En la práctica vas a armar tu propio pipeline. Nos vemos ahí."}],"9":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Una buena idea mal documentada termina en caos","sub":"Detectaste una oportunidad. Ahora hay que convertirla en una solución clara que cualquiera pueda construir.","cap":"Detectar una oportunidad no basta: hay que traducirla en una solución documentada que el equipo pueda construir sin adivinar.","narr":"Bienvenido a esta lección. Ya sabes detectar procesos que vale la pena automatizar. Pero una buena idea, mal documentada, termina en caos: cada quien la entiende distinto. Aquí vas a aprender a traducir esa idea en una solución clara, y a llevar el proyecto de principio a fin."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro cosas, en pocos minutos","items":[["1","PDD y SDD","los documentos que evitan el caos"],["2","El diseño TO-BE","cómo se ve el proceso mejorado"],["3","El ciclo de vida","del análisis al go-live"]],"cap":"En esta lección: qué son el PDD y el SDD, cómo diseñar el TO-BE, el ciclo de vida del proyecto y cómo validar antes de salir a producción.","narr":"Vas a entender cuatro cosas: qué son el PDD y el SDD y para qué sirven, cómo se diseña el estado mejorado de un proceso, cuáles son las fases de un proyecto de automatización, y cómo validar con el negocio antes de salir a producción."},{"type":"compare","dur":18,"eyeb":"Los dos documentos clave","h2":"PDD y SDD responden preguntas distintas","colA":["PDD","El qué","Process Definition Document. Describe el proceso: qué hace, con qué reglas, paso a paso. Lo escribe el analista con el negocio."],"colB":["SDD","El cómo","Solution Design Document. Describe la solución técnica: cómo se va a construir. Lo escribe quien diseña la automatización."],"cap":"El PDD documenta QUÉ hace el proceso y con qué reglas. El SDD documenta CÓMO se va a construir la solución técnica.","narr":"Empecemos por los dos documentos que evitan el caos. El PDD, o Process Definition Document, describe el qué: cómo funciona el proceso, con qué reglas, paso a paso. El SDD, o Solution Design Document, describe el cómo: la forma técnica de construirlo. Uno es el mapa del proceso; el otro, el plano de la solución."},{"type":"pieces","dur":16,"eyeb":"Anatomía del PDD","h2":"Un buen PDD tiene cuatro partes","pieces":[["🎯","Objetivo","Qué resuelve y por qué"],["👣","Pasos","El proceso, acción por acción"],["📏","Reglas","Qué decidir en cada caso"],["⚠️","Excepciones","Qué hacer cuando algo falla"]],"cap":"Un PDD sólido cubre: objetivo del proceso, pasos detallados, reglas de negocio y qué hacer ante las excepciones.","narr":"Un buen PDD tiene cuatro partes. El objetivo: qué resuelve y por qué importa. Los pasos: el proceso descrito acción por acción, sin dar nada por obvio. Las reglas de negocio: qué decidir en cada situación. Y las excepciones: qué hacer cuando algo se sale de lo normal. Si esas cuatro están claras, quien construya no tendrá que adivinar."},{"type":"define","dur":15,"eyeb":"El concepto central","h2":"Antes de automatizar, diseña el TO-BE","def":"El <b>TO-BE</b> es cómo <b>debería</b> funcionar el proceso una vez mejorado, en contraste con el <b>AS-IS</b>, que es cómo funciona hoy con todos sus defectos.","cap":"El AS-IS es el proceso como es hoy; el TO-BE es como debería quedar, ya rediseñado y libre de los pasos inútiles.","narr":"Aquí va una idea central. El AS-IS es cómo funciona el proceso hoy, con todos sus rodeos y defectos. El TO-BE es cómo debería funcionar una vez mejorado. La regla de oro: nunca automatices el AS-IS tal cual. Primero rediseñas, y después construyes."},{"type":"spot","dur":16,"snum":"La trampa más común","sic":"🚫","stitle":"No automatices el desorden","stext":"Si automatizas un proceso torpe, obtienes un proceso torpe... pero más rápido. El error se multiplica, no desaparece.","sex":"primero ordena · después automatiza","cap":"Automatizar un proceso desordenado solo lo vuelve un desorden más rápido: primero simplificas, luego automatizas.","narr":"Cuidado con la trampa más común. Si automatizas un proceso torpe, no lo arreglas: obtienes lo mismo, pero más rápido. El error se multiplica en lugar de desaparecer. Por eso el TO-BE va primero: eliminas pasos inútiles, simplificas las reglas, y recién entonces automatizas lo que de verdad vale la pena."},{"type":"flow","dur":17,"eyeb":"Del AS-IS al TO-BE","h2":"Rediseñar es quitar, no solo mover","nodes":[["📋","AS-IS","El proceso actual"],["✂️","Depura","Quita pasos inútiles"],["🧠","Añade criterio","Dónde entra la IA"],["✨","TO-BE","El proceso mejorado"]],"cap":"Se pasa del AS-IS al TO-BE depurando pasos que no aportan y sumando IA donde aporta criterio, no en todos lados.","narr":"Veamos cómo se pasa de uno al otro. Tomas el proceso actual, el AS-IS. Le quitas los pasos que no aportan valor. Identificas dónde la inteligencia artificial suma criterio de verdad, no en todos lados. Y con eso llegas al TO-BE, el proceso mejorado. Rediseñar es, sobre todo, quitar; no solo mover cajas de lugar."},{"type":"flow","dur":18,"eyeb":"El ciclo de vida","h2":"Todo proyecto recorre las mismas fases","nodes":[["🔍","Análisis","Entender y documentar"],["📐","Diseño","PDD, SDD y TO-BE"],["🛠️","Desarrollo","Construir y probar"],["🚀","Producción","Salir y estabilizar"]],"cap":"El proyecto va de análisis (entender) a diseño (documentar), desarrollo (construir) y producción (salir a operar).","narr":"Con los documentos y el TO-BE listos, el proyecto avanza por fases. Análisis: entender y documentar el proceso. Diseño: el PDD, el SDD y el TO-BE que acabamos de ver. Desarrollo: construir la automatización y probarla. Y producción: salir a operar. Cada fase entrega algo concreto a la siguiente; saltarse una se paga caro después."},{"type":"define","dur":15,"eyeb":"La prueba con el negocio","h2":"El UAT es el examen final del proyecto","def":"El <b>UAT</b> (User Acceptance Testing) es la prueba donde el <b>negocio</b>, no el equipo técnico, valida que la solución hace lo que se pidió, con casos reales.","cap":"En el UAT es el usuario del negocio quien prueba la solución con casos reales y confirma que resuelve lo que se pidió.","narr":"Antes de salir a producción hay un examen final: el UAT, o prueba de aceptación del usuario. Aquí no prueba el equipo técnico, sino el negocio: la persona que usa el proceso todos los días. Con casos reales, confirma que la solución hace lo que pidió. Si el negocio no aprueba, no se sale. Así de simple."},{"type":"list","dur":17,"eyeb":"Criterios de aceptación","h2":"Aprobar no puede ser una opinión","items":[["✅","Medibles","Se cumplen o no, sin ambigüedad"],["📝","Acordados antes","Se definen al inicio, no al final"],["🎯","Sobre el resultado","Qué debe lograr, no cómo"]],"cap":"Los criterios de aceptación deben ser medibles, acordados desde el inicio y centrados en el resultado esperado, no en gustos.","narr":"Para que el UAT no dependa del humor de nadie, defines criterios de aceptación. Tienen que ser medibles: se cumplen o no, sin discusión. Acordados desde el inicio, no inventados al final. Y centrados en el resultado esperado, no en gustos personales. Un criterio claro convierte aprobar en un hecho, no en una opinión."},{"type":"spot","dur":16,"snum":"Después del go-live","sic":"🩺","stitle":"El hypercare","stext":"Los primeros días en producción se vigila de cerca: fallos reales aparecen con datos reales. Es parte del proyecto, no un extra.","sex":"acompañar · corregir · estabilizar","cap":"Tras el go-live viene el hypercare: un periodo de vigilancia cercana para corregir lo que solo aparece con datos reales.","narr":"El proyecto no termina el día que sale a producción. Justo después viene el hypercare: unos días de vigilancia cercana. Con datos reales aparecen situaciones que ninguna prueba anticipó. Acompañas, corriges y estabilizas. Planéalo desde el inicio: el hypercare es parte del proyecto, no un favor que haces al final."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas para no tropezar","myths":[["El papeleo no frena",", te ahorra retrabajo caro"],["La IA no diseña por ti",", ordena tu criterio, no lo reemplaza"],["Documentar no es de una vez",", el documento vive y se actualiza"]],"cap":"Documentar no es burocracia: evita retrabajo. La IA agiliza, no decide el diseño. Y el PDD es un documento vivo, no una foto.","narr":"Tres advertencias sanas antes de cerrar. Documentar no es burocracia que frena: te ahorra retrabajo carísimo más adelante. La inteligencia artificial ayuda a redactar y ordenar, pero no diseña la solución por ti: tu criterio manda. Y el documento no se escribe una sola vez: vive y se actualiza mientras el proceso cambia."},{"type":"pieces","dur":14,"eyeb":"Recapitulemos","h2":"El camino completo, en cuatro hitos","pieces":[["📄","Documenta","PDD y SDD"],["✨","Rediseña","El TO-BE"],["🔄","Ejecuta","El ciclo de vida"],["✅","Valida","UAT y go-live"]],"cap":"Recap: documenta con PDD y SDD, rediseña con el TO-BE, ejecuta el ciclo de vida y valida con UAT antes del go-live.","narr":"Recapitulemos el camino. Documentas el qué y el cómo con el PDD y el SDD. Rediseñas el proceso con el TO-BE antes de tocar nada. Ejecutas las fases del ciclo de vida en orden. Y validas con el negocio en el UAT antes del go-live. Cuatro hitos que convierten una idea en una solución que aguanta."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Una solución bien diseñada se construye una vez","sub":"Ya sabes documentar, rediseñar y llevar el proyecto de punta a punta. Sigue: aplicarlo en un caso real.","cap":"Documentar bien y rediseñar antes de automatizar hace que la solución se construya una vez y funcione: ahora toca aplicarlo.","narr":"Eso es el diseño funcional. Una solución bien documentada y bien rediseñada se construye una vez, y funciona; una improvisada se rehace tres veces. Ya sabes redactar los documentos, diseñar el TO-BE y llevar el proyecto de punta a punta. Ahora sigue lo importante: aplicarlo en un caso real. Nos vemos en la práctica."}],"10":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Antes de automatizar un proceso, hay que dibujarlo bien","sub":"Si negocio y quien automatiza no hablan el mismo idioma, el proyecto se tuerce desde el inicio.","cap":"Antes de automatizar un proceso hay que dibujarlo con claridad, en un idioma que todos entiendan.","narr":"Bienvenido a esta lección. Antes de automatizar cualquier proceso, hay que dibujarlo con claridad. Cuando el negocio y quien automatiza no hablan el mismo idioma, el proyecto se tuerce desde el arranque. Para eso existe BPMN, y hoy lo vas a entender."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Tres cosas, en pocos minutos","items":[["1","Qué es BPMN","y por qué es la lengua franca del proceso"],["2","Sus piezas base","eventos, tareas y compuertas"],["3","Un proceso completo","modelado y listo para automatizar"]],"cap":"En esta lección: qué es BPMN, sus piezas base y cómo se ve un proceso completo listo para automatizar.","narr":"En los próximos minutos vas a entender tres cosas. Qué es BPMN y por qué se volvió la lengua franca de los procesos. De qué piezas básicas está hecho. Y cómo se ve un proceso completo, modelado y listo para automatizar."},{"type":"define","dur":16,"eyeb":"El concepto base","h2":"Primero, qué es BPMN","def":"<b>BPMN 2.0</b> es un estándar visual para dibujar procesos con símbolos fijos, de modo que <b>negocio y tecnología</b> lean exactamente lo mismo en el mismo diagrama.","cap":"BPMN 2.0 es un estándar visual con símbolos fijos para que negocio y tecnología lean lo mismo.","narr":"Empecemos por la base. BPMN, en su versión dos punto cero, es un estándar visual para dibujar procesos. Su gracia es que usa símbolos fijos, con un significado acordado. Así el área de negocio y quien lo va a automatizar leen exactamente lo mismo en el mismo diagrama."},{"type":"pieces","dur":17,"eyeb":"La anatomía","h2":"Casi todo BPMN se arma con cuatro piezas","pieces":[["⭕","Evento","Algo que pasa: inicio o fin"],["🔲","Tarea","Un trabajo que se hace"],["🔷","Compuerta","Una decisión o bifurcación"],["➡️","Flujo","La flecha que conecta todo"]],"cap":"BPMN se arma con eventos (algo pasa), tareas (un trabajo), compuertas (una decisión) y flujos (las flechas).","narr":"Aunque BPMN tiene muchos símbolos, casi todo se arma con cuatro piezas. El evento: algo que ocurre, como el inicio o el fin. La tarea: un trabajo que se realiza. La compuerta: una decisión que bifurca el camino. Y el flujo: la flecha que conecta todo en orden."},{"type":"spot","dur":15,"snum":"Pieza 1 de 3","sic":"⭕","stitle":"Los eventos","stext":"Marcan que algo sucede. El círculo fino inicia el proceso; el grueso lo termina.","sex":"Llega un pedido · se vence un plazo · termina el flujo","cap":"Los eventos marcan que algo sucede: el círculo fino inicia el proceso y el grueso lo termina.","narr":"Veamos las tres piezas clave, una por una. Primero, los eventos: marcan que algo sucede. Un círculo de línea fina inicia el proceso, por ejemplo, cuando llega un pedido. Uno de línea gruesa lo termina. Entre medio pueden aparecer eventos intermedios, como el vencimiento de un plazo."},{"type":"spot","dur":15,"snum":"Pieza 2 de 3","sic":"🔲","stitle":"Las tareas","stext":"Cada rectángulo es un trabajo concreto. Un pequeño ícono indica quién lo hace: persona o sistema.","sex":"Revisar la factura · enviar el correo · registrar el dato","cap":"Cada tarea es un rectángulo: un trabajo concreto, hecho por una persona o por un sistema.","narr":"Segunda pieza, las tareas. Cada rectángulo es un trabajo concreto: revisar una factura, enviar un correo, registrar un dato. Un pequeño ícono dentro te dice quién la ejecuta: una persona o un sistema. Ese detalle importa cuando decides qué parte se puede automatizar."},{"type":"spot","dur":16,"snum":"Pieza 3 de 3","sic":"🔷","stitle":"Las compuertas","stext":"El rombo decide el camino. Según una condición, el flujo va por una rama o por otra.","sex":"¿Monto mayor a mil? · ¿cliente nuevo? · ¿aprobado o rechazado?","cap":"La compuerta es un rombo que decide el camino: según una condición, el flujo va por una rama u otra.","narr":"Tercera pieza, las compuertas, dibujadas como un rombo. Aquí el proceso decide. Según una condición, el flujo toma una rama u otra. ¿El monto supera los mil pesos? ¿El cliente es nuevo? Estas preguntas, bien puestas, son las que hacen que un proceso refleje la realidad y no una versión ideal."},{"type":"compare","dur":18,"eyeb":"Las compuertas más usadas","h2":"No todas las compuertas deciden igual","colA":["Exclusiva","Elige un solo camino","Toma una sola rama según la condición. O una, o la otra. Es la decisión de siempre."],"colB":["Paralela","Abre varios a la vez","Dispara todas las ramas al mismo tiempo y luego espera a que terminen. Sin condición."],"cap":"Compuerta exclusiva: elige un solo camino. Compuerta paralela: dispara varias ramas a la vez y las espera.","narr":"Conviene distinguir dos compuertas. La exclusiva elige un solo camino: o una rama, o la otra, según la condición. Es la decisión de toda la vida. La paralela es distinta: abre varias ramas al mismo tiempo, sin condición, y luego espera a que todas terminen. Confundirlas cambia por completo el resultado."},{"type":"flow","dur":18,"eyeb":"Quién hace qué","h2":"Pools y lanes: cada actor en su carril","nodes":[["🏊","Pool","El proceso completo"],["🛣️","Lane","Un actor: área o sistema"],["👤","Ventas","Su tarea"],["🤖","Sistema","Su tarea"]],"cap":"El pool es todo el proceso; cada lane es un actor. Así se ve, de un vistazo, quién hace cada tarea.","narr":"Un proceso real involucra a varios. Para mostrarlo, BPMN usa carriles. El pool es el proceso completo, la piscina. Dentro, cada lane, o carril, es un actor: un área o un sistema. Colocas cada tarea en el carril de quien la hace. Así, de un vistazo, se ve quién es responsable de qué."},{"type":"flow","dur":19,"eyeb":"Un proceso real","h2":"Aprobación de una solicitud, de inicio a fin","nodes":[["⭕","Inicio","Llega la solicitud"],["🔲","Revisar","Se valida el monto"],["🔷","¿Aprobado?","Sí o no"],["⭕","Fin","Se notifica"]],"cap":"Ejemplo: llega la solicitud, se revisa el monto, la compuerta decide aprobado o no, y se notifica el resultado.","narr":"Juntemos todo en un caso. Llega una solicitud, ese es el evento de inicio. Una tarea revisa el monto. Una compuerta pregunta si se aprueba: si sí, se registra; si no, se rechaza. En ambos casos se notifica al solicitante y el proceso termina. Piezas simples, proceso completo."},{"type":"chips","dur":15,"eyeb":"Con qué se dibuja","h2":"Herramientas para modelar en BPMN","chips":[["✏️","bpmn.io"],["🧩","Camunda"],["🔷","Bizagi"],["📐","Lucidchart"],["➕","y más"]],"cap":"Se modela en herramientas visuales como bpmn.io, Camunda, Bizagi o Lucidchart. Todas usan los mismos símbolos.","narr":"Todo esto se dibuja en herramientas visuales, como bpmn.io, Camunda, Bizagi o Lucidchart. Como BPMN es un estándar, los símbolos son iguales en todas. Aprendes la notación una vez y la puedes leer en cualquier lugar donde trabajes."},{"type":"myth","dur":17,"eyeb":"A tener en cuenta","h2":"Tres cosas que conviene entender bien","myths":[["No es un dibujo bonito",", es un acuerdo entre negocio y tecnología"],["Un buen modelo no lo hace la IA sola",", ella ordena, tú validas la realidad"],["Modelar no es automatizar",", primero el proceso claro, después el bot"]],"cap":"BPMN es un acuerdo, no un adorno. La IA ordena el borrador, tú validas. Y modelar bien va antes de automatizar.","narr":"Un punto importante antes de cerrar. Un diagrama BPMN no es un dibujo bonito: es un acuerdo entre negocio y tecnología. La inteligencia artificial puede ordenarte un primer borrador, pero eres tú quien valida que refleje la realidad. Y modelar no es automatizar: primero el proceso claro, después el bot."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Un buen BPMN es el plano de tu automatización","sub":"Ya sabes leer eventos, tareas y compuertas. Sigue: modelar un proceso tuyo y prepararlo para automatizar.","cap":"Un buen BPMN es el plano de tu automatización. Sigue: modelar un proceso propio y prepararlo para el bot.","narr":"Recapitulemos. BPMN dibuja procesos con eventos, tareas y compuertas, y los ordena por carriles según quién hace qué. Ese diagrama es el plano de tu automatización. Ya sabes leerlo; ahora sigue lo mejor: modelar un proceso tuyo y prepararlo para el bot. Nos vemos en la práctica."}]};
